	@Test
	void bindsPolicyDnsResolutionToTheConnection(MockServerClient server) throws Exception {
		URI target = URI.create("http://localhost:" + server.getPort() + "/dns-rebind");
		server.when(request().withMethod("GET").withPath("/dns-rebind"))
				.respond(response().withStatusCode(200).withBody("must not be reached"));
		AtomicInteger resolutions = new AtomicInteger();
		PublicNetworkAccessPolicy policy = new PublicNetworkAccessPolicy(host -> resolutions.getAndIncrement() == 0
				? new InetAddress[] { InetAddress.getByName("8.8.8.8") }
				: new InetAddress[] { InetAddress.getByName("127.0.0.1") });

		try (RDF4JHttpClient client = new ApacheHC5RDF4JHttpClientFactory().create(
				RDF4JHttpClientConfig.newBuilder().remoteResourceAccessPolicy(policy).build())) {
			assertThatThrownBy(() -> client.execute(HttpRequest.newBuilder("GET", target).build()))
					.isInstanceOf(IOException.class)
					.hasMessageContaining("127.0.0.1")
					.hasMessageContaining("not globally routable");
		}

		assertThat(resolutions).hasValue(2);
		server.verify(request().withMethod("GET").withPath("/dns-rebind"),
				org.mockserver.verify.VerificationTimes.exactly(0));
	}

	@Test
	void stripsCredentialsAndSensitiveHeadersFromCrossOriginRedirect() {
		PolicyAwareRedirectStrategy strategy = new PolicyAwareRedirectStrategy(RemoteResourceAccessPolicy.allowAll());
		BasicHttpRequest redirect = new BasicHttpRequest("GET", "https://destination.example/resource");
		redirect.addHeader("Authorization", "Bearer secret");
		redirect.addHeader("Proxy-Authorization", "Basic secret");
		redirect.addHeader("Cookie", "session=secret");
		redirect.addHeader("Cookie2", "legacy=secret");
		redirect.addHeader(new BasicHeader("X-Private", "secret", true));
		redirect.addHeader("Accept", "text/turtle");
		BasicHttpContext context = new BasicHttpContext();

		assertThat(strategy.isRedirectAllowed(
				new HttpHost("https", "source.example", 443),
				new HttpHost("https", "destination.example", 443), redirect, context)).isTrue();

		assertThat(redirect.containsHeader("Authorization")).isFalse();
		assertThat(redirect.containsHeader("Proxy-Authorization")).isFalse();
		assertThat(redirect.containsHeader("Cookie")).isFalse();
		assertThat(redirect.containsHeader("Cookie2")).isFalse();
		assertThat(redirect.containsHeader("X-Private")).isFalse();
		assertThat(redirect.getFirstHeader("Accept").getValue()).isEqualTo("text/turtle");

		redirect.addHeader("Cookie", "re-added-by-cookie-store=secret");
		PolicyAwareRedirectStrategy.stripRedirectedCredentials(redirect, context);
		assertThat(redirect.containsHeader("Cookie")).isFalse();
	}

	@Test
	void followsCrossOriginRedirectWithoutRequestOrDefaultCredentials(MockServerClient server) throws Exception {
		AtomicReference<List<String>> authorizations = new AtomicReference<>();
		AtomicReference<List<String>> cookies = new AtomicReference<>();
		HttpServer destination = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		destination.createContext("/destination", exchange -> {
			authorizations.set(exchange.getRequestHeaders().get("Authorization"));
			cookies.set(exchange.getRequestHeaders().get("Cookie"));
			exchange.sendResponseHeaders(200, 0);
			exchange.close();
		});
		destination.start();
		try {
			URI initialTarget = URI.create("http://127.0.0.1:" + server.getPort() + "/credential-source");
			URI redirectedTarget = URI.create(
					"http://127.0.0.1:" + destination.getAddress().getPort() + "/destination");
			server.when(request().withMethod("GET").withPath("/credential-source"))
					.respond(response().withStatusCode(302).withHeader("Location", redirectedTarget.toString()));

			try (RDF4JHttpClient client = new ApacheHC5RDF4JHttpClientFactory().create(
					RDF4JHttpClientConfig.newBuilder()
							.defaultHeader("Cookie", "session=default-secret")
							.build());
					org.eclipse.rdf4j.http.client.spi.HttpResponse ignored = client.execute(
							HttpRequest.newBuilder("GET", initialTarget)
									.header("Authorization", "Bearer request-secret")
									.build())) {
				assertThat(ignored.getStatusCode()).isEqualTo(200);
			}

			assertThat(authorizations.get()).isNull();
			assertThat(cookies.get()).isNull();
		} finally {
			destination.stop(0);
		}
	}

