	@Test
	void rejectsRedirectTargetBeforeRedirectConnection(MockServerClient server) throws Exception {
		URI initialTarget = URI.create("http://127.0.0.1:" + server.getPort() + "/start");
		URI redirectedTarget = URI.create("http://127.0.0.1:" + server.getPort() + "/blocked");
		server.when(request().withMethod("GET").withPath("/start"))
				.respond(response().withStatusCode(302).withHeader("Location", redirectedTarget.toString()));
		server.when(request().withMethod("GET").withPath("/blocked"))
				.respond(response().withStatusCode(200).withBody("must not be reached"));
		IOException denied = new IOException("redirect denied by test policy");
		RemoteResourceAccessPolicy policy = mock(RemoteResourceAccessPolicy.class);
		doThrow(denied).when(policy).checkRedirect(initialTarget, redirectedTarget);

		try (RDF4JHttpClient client = new ApacheHC5RDF4JHttpClientFactory().create(
				RDF4JHttpClientConfig.newBuilder().remoteResourceAccessPolicy(policy).build())) {
			assertThatThrownBy(() -> client.execute(HttpRequest.newBuilder("GET", initialTarget).build()))
					.isSameAs(denied);
		}
	}

	@Test
	void revalidatesBeforeExplicitResponseRetry() throws Exception {
		URI target = URI.create("https://example.org/resource");
		IOException rebound = new IOException("rebound to private address");
		RemoteResourceAccessPolicy policy = mock(RemoteResourceAccessPolicy.class);
		doNothing().doThrow(rebound).when(policy).checkInitial(target);
		ClassicHttpResponse timeout = mock(ClassicHttpResponse.class);
		when(timeout.getCode()).thenReturn(408);
		CloseableHttpClient transport = mock(CloseableHttpClient.class);
		when(transport.executeOpen(isNull(HttpHost.class), any(ClassicHttpRequest.class), isNull(HttpContext.class)))
				.thenReturn(timeout);
		ApacheHC5RDF4JHttpClient client = new ApacheHC5RDF4JHttpClient(transport, 2, RequestConfig.DEFAULT, policy);

		assertThatThrownBy(() -> client.execute(HttpRequest.newBuilder("GET", target).build())).isSameAs(rebound);

		verify(policy, times(2)).checkInitial(target);
		verify(transport).executeOpen(isNull(HttpHost.class), any(ClassicHttpRequest.class), isNull(HttpContext.class));
		verify(timeout).close();
	}
